#pragma once

#include <unordered_map>
#include <cstdint>

#include "Math.hpp"
#include "Weapon.hpp"

namespace llm_npc {

// All mutable state for the human player. Owned by World so combat logic
// in World::updateCombat can read and write it without touching main.cpp.
// main.cpp syncs camera.position FROM player.position each frame.
struct Player {
    // World-space feet position. main.cpp writes this from camera movement;
    // combat reads it for hit detection.
    Vec3 position{};

    // Hit points. 0 means dead → game over.
    int hp     = 100;
    int hpMax  = 100;

    // Currently equipped weapon. Switch via world.playerSwitchWeapon().
    WeaponKind weapon = WeaponKind::Fist;

    // Ammo remaining per weapon kind. Melee weapons (Fist) are not tracked
    // here — use weaponDef(k).ammoMax == 0 to detect melee.
    std::unordered_map<std::uint8_t, int> ammo;

    // Constructor initialises ranged ammo from the weapon definitions table.
    Player() {
        ammo[static_cast<std::uint8_t>(WeaponKind::Pistol)] =
            weaponDef(WeaponKind::Pistol).ammoMax;
    }

    // Seconds remaining before the player can attack again.
    float attackCooldown = 0.f;

    // 0→1 fraction used to drive the weapon swing/recoil animation.
    // Increments to 1 on attack, decays back to 0 over ~0.15 s.
    float attackAnimFraction = 0.f;

    bool alive() const { return hp > 0; }

    // Returns current ammo for the equipped ranged weapon; -1 for melee.
    int currentAmmo() const {
        const auto& def = weaponDef(weapon);
        if (def.ammoMax == 0) return -1;
        const auto it = ammo.find(static_cast<std::uint8_t>(weapon));
        return it != ammo.end() ? it->second : 0;
    }
};

}  // namespace llm_npc

#pragma once

#include <array>
#include <cstdint>

namespace llm_npc {

// The two weapon kinds available in v1. Fist is always available; Pistol
// requires ammo. Expand this enum when adding new weapon types.
enum class WeaponKind : std::uint8_t {
    Fist = 0,
    Pistol = 1,
};

// Static data for one weapon type. All values are design constants — never
// mutated at runtime.
struct WeaponDef {
    const char* name;       // display name for HUD ("Fist", "Pistol")
    int         damage;     // hit points subtracted per successful hit
    float       range;      // maximum distance (world units) a hit can land
    int         ammoMax;    // magazine/pool capacity; 0 = melee (unlimited)
    float       fireCooldown; // minimum seconds between attacks
    float       accuracy;   // 0.0–1.0 base hit probability (1.0 = always hits)
};

// Indexed by WeaponKind. Add a row here when adding a new WeaponKind variant.
inline constexpr std::array<WeaponDef, 2> kWeaponDefs{{
    // Fist
    {"Fist",   15, 1.8f,  0,  0.40f, 1.0f},
    // Pistol
    {"Pistol", 35, 30.0f, 12, 0.55f, 0.70f},
}};

// Guard: the table must have one entry per WeaponKind variant.
static_assert(std::tuple_size<decltype(kWeaponDefs)>::value == 2,
              "kWeaponDefs size must match WeaponKind variant count");

// Convenience: returns the definition for a given kind.
inline const WeaponDef& weaponDef(WeaponKind k) {
    return kWeaponDefs[static_cast<std::size_t>(k)];
}

}  // namespace llm_npc

