17	    Stop,        // hold position, face the player
18	    Face,        // turn to look at the player, don't move
19	    RaiseHand,   // raise the right hand for a few seconds
20	    Wave,        // wave the right hand for a few seconds
21	    Arrest,      // police only: chase the player down, then stop on catch
22	    CallPolice,  // civilians: summon the police to come arrest the player
23	    ReturnHome,  // not LLM-emittable: walk back to the spawn spot
24	};
