26	// The NPC's emotional read on the conversation, also emitted by the LLM as a
27	// tag on every reply. Drives the rendered facial expression.
28	enum class NpcMood {
29	    Neutral,
30	    Happy,
31	    Angry,
32	    Sad,
33	    Embarrassed,
34	    Surprised,
35	};
