44	// Maps a normalized (lowercase, '_'-joined) tag keyword to its action.
45	// Unknown keywords yield None. ReturnHome is internal and not mapped.
46	inline NpcAction actionFromKeyword(const std::string& kw) {
47	    if (kw == "follow") return NpcAction::Follow;
48	    if (kw == "stop" || kw == "stay") return NpcAction::Stop;
49	    if (kw == "face" || kw == "look") return NpcAction::Face;
50	    if (kw == "raise_hand" || kw == "raise") return NpcAction::RaiseHand;
51	    if (kw == "wave") return NpcAction::Wave;
52	    if (kw == "arrest") return NpcAction::Arrest;
53	    if (kw == "call_police" || kw == "police") return NpcAction::CallPolice;
54	    return NpcAction::None;
55	}
56	
57	// Maps a normalized mood keyword to a mood, with synonyms for the words small
58	// models actually emit. Unknown keywords yield Neutral with `ok = false`.
59	inline bool moodFromKeyword(const std::string& kw, NpcMood& out) {
60	    if (kw == "neutral" || kw == "calm") out = NpcMood::Neutral;
61	    else if (kw == "happy" || kw == "flattered" || kw == "pleased" ||
62	             kw == "excited" || kw == "joyful" || kw == "amused") out = NpcMood::Happy;
63	    else if (kw == "angry" || kw == "annoyed" || kw == "irritated" ||
64	             kw == "frustrated" || kw == "mad") out = NpcMood::Angry;
65	    else if (kw == "sad" || kw == "upset" || kw == "hurt" ||
66	             kw == "disappointed") out = NpcMood::Sad;
67	    else if (kw == "embarrassed" || kw == "flustered" || kw == "awkward" ||
68	             kw == "shy" || kw == "nervous") out = NpcMood::Embarrassed;
69	    else if (kw == "surprised" || kw == "shocked" || kw == "startled") out = NpcMood::Surprised;
70	    else return false;
71	    return true;
72	}
73	
74	// Lowercase copy of s (ASCII), used for case-insensitive matching.
75	inline std::string toLowerAscii(const std::string& s) {
76	    std::string out = s;
77	    for (char& c : out) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
78	    return out;
79	}
