81	// Extracts every directive tag from an LLM reply, tolerating the mess a small
82	// model actually produces: tags at the start, middle, or end; doubled or
83	// single brackets; duplicate mood tags (the last one wins); unknown keywords.
84	// All recognized-looking tags ("action"/"mood" kinds) are erased from `reply`
85	// in place - including unknown keywords, so brackets never reach the
86	// transcript - and seam whitespace is collapsed. Other bracketed text (e.g.
87	// "[sigh]" or "[[1]]") is left alone.
88	inline Directives parseDirectives(std::string& reply) {
89	    Directives out;
90	
91	    std::size_t i = 0;
92	    while (i < reply.size()) {
93	        if (reply[i] != '[') {
94	            ++i;
95	            continue;
96	        }
97	        const std::size_t open = i;
98	        std::size_t inner = open + 1;
99	        if (inner < reply.size() && reply[inner] == '[') ++inner;  // "[[" form
100	        const std::size_t close = reply.find(']', inner);
101	        if (close == std::string::npos) break;  // no closing bracket anywhere
102	        std::size_t end = close + 1;
103	        // Consume a second ']' if present so "]]" closes fully.
104	        if (end < reply.size() && reply[end] == ']') ++end;
105	
106	        // "kind : keyword" between the brackets.
107	        const std::string body = toLowerAscii(reply.substr(inner, close - inner));
108	        const std::size_t colon = body.find(':');
109	        if (colon == std::string::npos) {
110	            ++i;
111	            continue;
112	        }
113	        const auto trimRange = [&](std::size_t b, std::size_t e) {
114	            while (b < e && std::isspace(static_cast<unsigned char>(body[b]))) ++b;
115	            while (e > b && std::isspace(static_cast<unsigned char>(body[e - 1]))) --e;
116	            return body.substr(b, e - b);
117	        };
118	        const std::string kind = trimRange(0, colon);
119	        std::string keyword = trimRange(colon + 1, body.size());
120	        // Normalize inner spaces to underscores ("call police" -> "call_police").
121	        for (char& c : keyword) {
122	            if (std::isspace(static_cast<unsigned char>(c))) c = '_';
123	        }
124	
125	        if (kind != "action" && kind != "mood") {
126	            ++i;
127	            continue;
128	        }
129	
130	        if (kind == "action") {
131	            const NpcAction action = actionFromKeyword(keyword);
132	            if (action != NpcAction::None) out.action = action;
133	        } else {
134	            NpcMood mood = NpcMood::Neutral;
135	            if (moodFromKeyword(keyword, mood)) {
136	                out.mood = mood;  // last recognized mood wins
137	                out.hasMood = true;
138	            }
139	        }
140	
141	        // Strip the tag and collapse the whitespace seam it leaves behind.
142	        reply.erase(open, end - open);
143	        while (open < reply.size() && open > 0 &&
144	               std::isspace(static_cast<unsigned char>(reply[open])) &&
145	               std::isspace(static_cast<unsigned char>(reply[open - 1]))) {
146	            reply.erase(open, 1);
147	        }
148	        i = open;
149	    }
150	
151	    // Tags at the very edges leave dangling whitespace; trim both ends.
152	    while (!reply.empty() && std::isspace(static_cast<unsigned char>(reply.back()))) reply.pop_back();
153	    std::size_t lead = 0;
154	    while (lead < reply.size() && std::isspace(static_cast<unsigned char>(reply[lead]))) ++lead;
155	    reply.erase(0, lead);
156	
157	    return out;
158	}
159	
160	// Compatibility wrapper: extract just the action (still strips all tags).
161	inline NpcAction parseActionTag(std::string& reply) {
162	    return parseDirectives(reply).action;
163	}
164	
165	}  // namespace llm_npc
