15	namespace llm_npc {
16	
17	// Combat state machine for an NPC. Civilians flee when damaged; armed NPCs
18	// (cops) turn Hostile and fight back. Orthogonal to the conversational
19	// behavior_ system — a Fleeing NPC still has a mood, but combat movement
20	// overrides behavior movement while active (World::updateCombat).
21	enum class NpcState {
22	    Idle,     // default; conversation and behaviors work normally
23	    Fleeing,  // moving away from the player at flee speed
24	    Hostile,  // armed NPC: moving to preferred range and firing
25	    Dead,     // hp reached 0; rendered collapsed, no further interaction
26	};
27	
28	// An NPC that delegates dialogue to the shared LlmClient. Holds its own persona
29	// and a bounded conversation history. Many NPCs can share one LlmClient.
30	class Npc {
31	   public:
32	    Npc(Persona persona, LlmClient& client, int maxHistoryTurns = 10);
33	
34	    // Sends the player's line to the LLM. Returns the in-flight request id.
35	    // The reply will appear in client.drainReplies() with that id; pass it back
36	    // into onReplyArrived() to update this NPC's history and surface text.
37	    std::uint64_t ask(const std::string& playerLine);
38	
39	    // Notify this NPC of a reply. Returns the assistant text if the id matches
40	    // a pending request from this NPC; nullopt otherwise. On success, the turn
41	    // is appended to history (capped to maxHistoryTurns_).
42	    std::optional<std::string> onReplyArrived(const ChatReply& reply);
43	
44	    // Places the NPC in the world: feet position, facing in degrees (0 looks
45	    // toward +Z), and the id of the building/prop they belong to. The spot is
46	    // remembered as "home" so ReturnHome can walk back to it later.
47	    void setPlacement(const Vec3& position, float facingDeg, std::string spotId) {
48	        position_ = position;
49	        facingDeg_ = facingDeg;
50	        homePosition_ = position;
51	        homeFacingDeg_ = facingDeg;
52	        spotId_ = std::move(spotId);
53	    }
54	
55	    // World-space feet position.
